SELECT publish_test_assert(NOT has_table_privilege('authenticated','provider_services','INSERT,UPDATE,DELETE'),'service table writes revoked');
SELECT publish_test_assert(NOT has_function_privilege('anon','save_provider_service(uuid,jsonb,uuid,integer)','EXECUTE'),'anonymous service creation revoked');
SELECT publish_test_assert(NOT has_table_privilege('anon','provider_service_catalog','INSERT,UPDATE,DELETE'),'public catalog is read-only');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a8111111-1111-4111-8111-111111111111',true);
SELECT set_config('publish_test.org',save_provider_draft('{"name":"Publication fixture","slug":"publication-fixture-a","provider_type":"grooming_business","email":"publication@example.invalid","city":"Ibadan","state":"Oyo","address":"12 Private Example Road"}')::text,true);
SELECT set_config('publish_test.service',save_provider_service(current_setting('publish_test.org')::uuid,'{"name":"Grooming session","description":"Provider-entered grooming service description.","category":"grooming","delivery_mode":"clinic_visit","duration_minutes":45,"base_price":12500.50}')::text,true);
SELECT publish_test_assert((SELECT count(*)=1 FROM provider_services WHERE NOT is_published),'services start as private drafts');
SELECT publish_test_reject($q$ SELECT set_provider_service_publication(current_setting('publish_test.service')::uuid,true,1) $q$,'unapproved organization cannot publish');
SELECT publish_test_reject($q$ SELECT save_provider_service(current_setting('publish_test.org')::uuid,'{"name":"Clinical service","description":"An unauthorized veterinary care offering.","category":"veterinary","delivery_mode":"clinic_visit","duration_minutes":30,"base_price":5000}') $q$,'organization cannot offer another professional category');
SELECT publish_test_reject($q$ SELECT save_provider_service(current_setting('publish_test.org')::uuid,'{"name":"Spoofed service","is_published":true}') $q$,'client cannot forge publication status');
SELECT publish_test_reject($q$ SELECT save_provider_service(current_setting('publish_test.org')::uuid,'{"name":"Video service","description":"An unsupported video consultation service.","category":"grooming","delivery_mode":"video","duration_minutes":30,"base_price":5000}') $q$,'unsupported video delivery rejected');
SELECT publish_test_reject($q$ SELECT save_provider_service(current_setting('publish_test.org')::uuid,'{"name":"Invalid price","description":"A service with an invalid fractional price.","category":"grooming","delivery_mode":"clinic_visit","duration_minutes":30,"base_price":5.123}') $q$,'fractional currency precision rejected');
SELECT set_config('request.jwt.claim.sub','a8222222-2222-4222-8222-222222222222',true);
SELECT publish_test_assert((SELECT count(*)=0 FROM provider_services),'other owner cannot read private services');
SELECT publish_test_reject($q$ SELECT set_provider_service_publication(current_setting('publish_test.service')::uuid,true,1) $q$,'other owner cannot publish known service');
SELECT publish_test_reject($q$ SELECT save_provider_service(current_setting('publish_test.org')::uuid,'{}') $q$,'other owner cannot save service');
SET LOCAL ROLE anon;
